import base64
import io
import zipfile
from pathlib import Path

DATA = """















TkVfUkVBRE1FLnR4dFVUBQADnYVPanV4CwABBAAAAAAEAAAAAFBLBQYAAAAABQAFAOcBAAAwKgAAAAA=
"""

def main():
    raw = base64.b64decode("".join(DATA.split()))
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        z.extractall(Path.cwd())
    print("FANDEX music chart pipeline v1 파일 생성 완료")
    print("생성 파일:")
    for name in [
        "music_chart_seed_v1_template.csv",
        "music_chart_publish_v1.py",
        "fandex_master_score_v6.py",
        "fandex_publish_all_v2.py",
        "MUSIC_CHART_PIPELINE_README.txt",
    ]:
        print("- " + name)

if __name__ == "__main__":
    main()
